import{_ as o,o as c,c as a,a3 as t}from"./chunks/framework.B8jMSdkO.js";const g=JSON.parse('{"title":"Command-Line Help for cypera","description":"","frontmatter":{},"headers":[],"relativePath":"reference/commands.md","filePath":"reference/commands.md"}'),d={name:"reference/commands.md"};function r(i,e,l,n,p,s){return c(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="command-line-help-for-cypera" tabindex="-1">Command-Line Help for <code>cypera</code> <a class="header-anchor" href="#command-line-help-for-cypera" aria-label="Permalink to &quot;Command-Line Help for `cypera`&quot;">​</a></h1><p>This document contains the help content for the <code>cypera</code> command-line program.</p><p>Reusable documentation/reference-generation utilities for the 9aia org</p><p><strong>Command Overview:</strong></p><ul><li><a href="#cypera"><code>cypera</code>↴</a></li><li><a href="#cypera-gen"><code>cypera gen</code>↴</a></li><li><a href="#cypera-gen-crate-map"><code>cypera gen crate-map</code>↴</a></li><li><a href="#cypera-gen-cli"><code>cypera gen cli</code>↴</a></li><li><a href="#cypera-gen-config"><code>cypera gen config</code>↴</a></li><li><a href="#cypera-gen-api"><code>cypera gen api</code>↴</a></li><li><a href="#cypera-check"><code>cypera check</code>↴</a></li></ul><h2 id="cypera" tabindex="-1"><code>cypera</code> <a class="header-anchor" href="#cypera" aria-label="Permalink to &quot;`cypera`&quot;">​</a></h2><p>Reusable documentation/reference-generation utilities for the 9aia org</p><p><strong>Usage:</strong> <code>cypera &lt;COMMAND&gt;</code></p><h6 id="commands" tabindex="-1"><strong>Commands:</strong> <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;**Commands:**&quot;">​</a></h6><ul><li><code>gen</code> — Generate a docs/reference page</li><li><code>check</code> — Lint a repo&#39;s docs contract — README/AGENTS shape, no CHANGELOG, no version-in-prose, Diátaxis docs site, generated-reference freshness, <code>docs:check</code> script</li></ul><h6 id="options" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>-h, --help</code> — Print help</li><li><code>-V, --version</code> — Print version</li></ul><h2 id="cypera-gen" tabindex="-1"><code>cypera gen</code> <a class="header-anchor" href="#cypera-gen" aria-label="Permalink to &quot;`cypera gen`&quot;">​</a></h2><p>Generate a docs/reference page</p><p><strong>Usage:</strong> <code>cypera gen &lt;COMMAND&gt;</code></p><h6 id="commands-1" tabindex="-1"><strong>Commands:</strong> <a class="header-anchor" href="#commands-1" aria-label="Permalink to &quot;**Commands:**&quot;">​</a></h6><ul><li><code>crate-map</code> — Crate map — workspace <code>Cargo.toml</code>s → crate/layer/purpose table (+ per-crate module sections when entry files exist). <code>cypera.toml [crate_map]</code> supplies layer overrides, the layer order, the default layer, splice targets, and the crate-api page</li><li><code>cli</code> — CLI reference — two modes:</li><li><code>config</code> — Config reference — two modes:</li><li><code>api</code> — Rustdoc API site — the <code>docs/gen-api*.py</code> port: <code>cargo doc --workspace --no-deps</code> in the repo, the real target dir resolved via <code>cargo metadata</code> (respects a configured <code>target-dir</code>), <code>&lt;target&gt;/doc</code> copied into the docs site&#39;s <code>public/api/</code>, and a styled crate index written to <code>index.html</code>. The output is a gitignored build artifact — <code>check</code> has nothing to freshness-gate. <code>[api]</code> in cypera.toml supplies <code>out</code>/<code>prefix</code>/<code>title</code>/ <code>target_dir</code>; every field is optional</li></ul><h6 id="options-1" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-1" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>-h, --help</code> — Print help</li></ul><h2 id="cypera-gen-crate-map" tabindex="-1"><code>cypera gen crate-map</code> <a class="header-anchor" href="#cypera-gen-crate-map" aria-label="Permalink to &quot;`cypera gen crate-map`&quot;">​</a></h2><p>Crate map — workspace <code>Cargo.toml</code>s → crate/layer/purpose table (+ per-crate module sections when entry files exist). <code>cypera.toml [crate_map]</code> supplies layer overrides, the layer order, the default layer, splice targets, and the crate-api page</p><p><strong>Usage:</strong> <code>cypera gen crate-map [OPTIONS]</code></p><h6 id="options-2" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-2" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--repo &lt;REPO&gt;</code> — Repo root (dir containing the workspace <code>Cargo.toml</code>). Default: current directory [default: .]</li><li><code>--config &lt;CONFIG&gt;</code> — Explicit <code>cypera.toml</code> path (default: discovered upward from <code>--repo</code>)</li><li><code>--out &lt;OUT&gt;</code> — Write a full page to this file instead of stdout. When the file exists and contains a <code>&lt;!-- crate-map --&gt;</code> marker, only the table after the marker is replaced. Overrides <code>[crate_map]</code> splices/crate_api</li><li><code>--layer &lt;LAYERS&gt;</code> — Layer override <code>crate-name=layer</code> (repeatable) — overrides <code>[crate_map.layers]</code> and the heuristic</li><li><code>-h, --help</code> — Print help</li></ul><h2 id="cypera-gen-cli" tabindex="-1"><code>cypera gen cli</code> <a class="header-anchor" href="#cypera-gen-cli" aria-label="Permalink to &quot;`cypera gen cli`&quot;">​</a></h2><p>CLI reference — two modes: - <code>--input &lt;file|-&gt;</code>: wrap <code>gen-cli-docs</code> markdown (clap-markdown) in a reference page. - otherwise: the <code>docs/gen-cli-docs.py</code> port — walk <code>&lt;bin&gt; &lt;prefix&gt;… &lt;sub&gt;… --help</code> recursively and emit the same page. The command spec comes from <code>--package</code>/<code>--bin</code>/ <code>--prefix</code> flags or <code>[cli]</code> in <code>cypera.toml</code>.</p><p><strong>Usage:</strong> <code>cypera gen cli [OPTIONS]</code></p><h6 id="options-3" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-3" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--repo &lt;REPO&gt;</code> — Repo root — cargo build + <code>cypera.toml</code> discovery base</li><li><code>--config &lt;CONFIG&gt;</code> — Explicit <code>cypera.toml</code> path</li><li><code>--input &lt;INPUT&gt;</code> — <code>gen-cli-docs</code> markdown file, or <code>-</code> for stdin. When given, wrap mode (no help walk)</li><li><code>--package &lt;PACKAGE&gt;</code> — Cargo package to <code>cargo build -q -p</code> first (config <code>[cli].package</code> fallback)</li><li><code>--bin &lt;BIN&gt;</code> — Binary under <code>target/debug/</code> — or a PATH executable when <code>--package</code> is unset (<code>[cli].bin</code>)</li><li><code>--prefix &lt;PREFIXES&gt;</code> — Argv prefix before the walked subcommand path, e.g. <code>run</code> for the driver <code>run</code> passthrough (repeatable; <code>[cli].prefix</code> fallback)</li><li><code>--title &lt;TITLE&gt;</code> — Page title override (<code>[cli].title</code> fallback; default is the python scripts&#39; <code>Command-Line Help for …</code> header)</li><li><code>--skip &lt;SKIPS&gt;</code> — Subcommand path to skip in the <code>--help</code> walk, space- joined (<code>driver exec</code>; repeatable; <code>[cli].skip</code> fallback)</li><li><code>--out &lt;OUT&gt;</code> — Write to this file instead of stdout (<code>[cli].out</code> fallback, then stdout)</li><li><code>-h, --help</code> — Print help (see a summary with &#39;-h&#39;)</li></ul><h2 id="cypera-gen-config" tabindex="-1"><code>cypera gen config</code> <a class="header-anchor" href="#cypera-gen-config" aria-label="Permalink to &quot;`cypera gen config`&quot;">​</a></h2><p>Config reference — two modes: - <code>--file &lt;rs&gt;…</code>: scan <code>pub struct</code> doc comments and render the generic page (<code>--only</code>/<code>--title</code> apply). - otherwise: the <code>docs/gen-config-docs.py</code> port — the curated <code>[config]</code> spec in <code>cypera.toml</code> (struct set, section titles, type vocabulary, prose sections).</p><p><strong>Usage:</strong> <code>cypera gen config [OPTIONS]</code></p><h6 id="options-4" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-4" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--repo &lt;REPO&gt;</code> — Repo root — <code>cypera.toml</code> discovery + relative <code>file</code> resolution base</li><li><code>--config &lt;CONFIG&gt;</code> — Explicit <code>cypera.toml</code> path</li><li><code>--file &lt;FILES&gt;</code> — Rust source file to scan (repeatable) — legacy mode</li><li><code>--only &lt;ONLY&gt;</code> — Only document these struct names (repeatable). Legacy mode; in <code>[config]</code> mode filters struct sections</li><li><code>--title &lt;TITLE&gt;</code> — Page title. Legacy mode default: <code>Config reference</code>; <code>[config]</code> mode: overrides <code>[config].title</code></li><li><code>--out &lt;OUT&gt;</code> — Write to this file instead of stdout (<code>[config].out</code> fallback, then stdout)</li><li><code>-h, --help</code> — Print help (see a summary with &#39;-h&#39;)</li></ul><h2 id="cypera-gen-api" tabindex="-1"><code>cypera gen api</code> <a class="header-anchor" href="#cypera-gen-api" aria-label="Permalink to &quot;`cypera gen api`&quot;">​</a></h2><p>Rustdoc API site — the <code>docs/gen-api*.py</code> port: <code>cargo doc --workspace --no-deps</code> in the repo, the real target dir resolved via <code>cargo metadata</code> (respects a configured <code>target-dir</code>), <code>&lt;target&gt;/doc</code> copied into the docs site&#39;s <code>public/api/</code>, and a styled crate index written to <code>index.html</code>. The output is a gitignored build artifact — <code>check</code> has nothing to freshness-gate. <code>[api]</code> in cypera.toml supplies <code>out</code>/<code>prefix</code>/<code>title</code>/ <code>target_dir</code>; every field is optional</p><p><strong>Usage:</strong> <code>cypera gen api [OPTIONS]</code></p><h6 id="options-5" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-5" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--repo &lt;REPO&gt;</code> — Repo root — the <code>cargo doc</code>/<code>cargo metadata</code> cwd. A <code>&lt;NAME&gt;_ROOT</code> env var (NAME = the cypera.toml dir&#39;s basename, uppercased — the python <code>TAMIAS_ROOT</code>/ <code>MYCO_ROOT</code>/… convention) overrides it, which is how detached-sha doc pipelines point at the real checkout. Default: current directory [default: .]</li><li><code>--config &lt;CONFIG&gt;</code> — Explicit <code>cypera.toml</code> path (default: discovered upward from <code>--repo</code>)</li><li><code>--out &lt;OUT&gt;</code> — API output <em>dir</em> override — replaces <code>[api].out</code>/<code>docs/public/api</code>; a relative path resolves against the cwd (run from the docs worktree to land in a detached docs checkout, the python <code>DOCS</code> anchor)</li><li><code>--target-dir &lt;TARGET_DIR&gt;</code> — Cargo target dir for the doc build — exported as <code>CARGO_TARGET_DIR</code> when unset (<code>[api].target_dir</code> fallback; the myco <code>target/docs-api</code> isolation)</li><li><code>-h, --help</code> — Print help</li></ul><h2 id="cypera-check" tabindex="-1"><code>cypera check</code> <a class="header-anchor" href="#cypera-check" aria-label="Permalink to &quot;`cypera check`&quot;">​</a></h2><p>Lint a repo&#39;s docs contract — README/AGENTS shape, no CHANGELOG, no version-in-prose, Diátaxis docs site, generated-reference freshness, <code>docs:check</code> script</p><p><strong>Usage:</strong> <code>cypera check [OPTIONS]</code></p><h6 id="options-6" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-6" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--repo &lt;REPO&gt;</code> — Repo root. Default: current directory [default: .]</li><li><code>--config &lt;CONFIG&gt;</code> — Explicit <code>cypera.toml</code> path (default: discovered upward from <code>--repo</code>)</li><li><code>--json</code> — Emit the report as JSON</li><li><code>-h, --help</code> — Print help</li></ul>',44)])])}const u=o(d,[["render",r]]);export{g as __pageData,u as default};
